        log.push({ha:F.A.hp,hb:F.B.hp,sa:F.A.sta,sb:F.B.sta,s:at===F.A?"A":"B",t:`${df.name} goes down! The referee starts the count… back on her feet`,k:"big",ev:"kd",an:at.name,dn:df.name});
