  if(G.rinTapeWk!=null&&G.rinTapeAbs==null)G.rinTapeAbs=oldPast(G.rinTapeWk,3);
  G.rinTapeWk=null;
  if(G.coachAway&&G.coachAwayAbs==null)G.coachAwayAbs=oldExpiry(G.coachAway,4);
