  /* v1.89.11: one lover became a list (several at once, Valentine can catch you) */
  if(!Array.isArray(G.lovers)){G.lovers=G.romance?[G.romance]:[];G.lovWk={};if(G.romance&&G.romWk!=null)G.lovWk[G.romance]=G.romWk;}
