const haremReady=G=>{const P=partners(G),fl=G.valFloor||{};return !!G.haremOK&&!G.harem&&P.length>=2&&G.valAbs!=null&&absWeek(G)-G.valAbs>=3&&P.every(k=>bondTot(G.F[k])>=Math.max(75,(fl[k]??0)+10)&&!isAway(G,k));};
