const metR=(G,id)=>G.F[id]&&G.F[id].met;
const tire=(G,v)=>roster(G).forEach(f=>f.fatigue=Math.max(0,Math.min(100,f.fatigue+v)));
const cheer=(G,v)=>roster(G).forEach(f=>f.morale=Math.max(0,Math.min(100,f.morale+v)));

